"""Reviewed introductory concept records, source-linked to the uploaded lecture.
Related retrieval/application exercises revisit concepts; they are not 600 unique
anatomical facts. No select-all questions or numeric parameter sweeps.
Run from repository root with python scripts/study-authoring/lymphatic.py.
"""
import json
from collections import Counter
from pathlib import Path
SOURCE='Lymphatic System Chapter 21 part 2.pptx'
questions=[]
def add(slides,kind,prompt,answer,wrong,explanation,clinical=False):
    source={'file':SOURCE,'slides':slides if isinstance(slides,list) else [slides],'kind':'clinical_application' if clinical else 'slide'}
    if clinical: source['rationale']='Introductory application of the cited lymphatic structure or function. '+explanation
    q=dict(id=f'lymphatic-{len(questions)+1:04d}',type=kind,difficulty='medium' if kind=='ordering' else 'easy',question=prompt,explanation=explanation,source=source)
    if kind=='fill_blank':q['answers']=answer.split('|')
    elif kind=='ordering':q.update(options=answer.split(' > '),correct=list(range(len(answer.split(' > ')))))
    else:q.update(options=[answer]+wrong.split('|'),correct=[0])
    questions.append(q)
def c(s,p,a,w,e,clinical=False):add(s,'multiple_choice',p,a,w,e,clinical)
def b(s,p,a,e,clinical=False):add(s,'fill_blank',p,a,'',e,clinical)
def o(s,p,a,e):add(s,'ordering',p,a,'',e,True)
